{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Samidorphan, a morphinan opioid with the same fused pentacyclic scaffold and tertiary amine, had an absolute oral bioavailability of 69% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Pethidine, an opioid with a basic N-methyl piperidine and moderate lipophilicity, showed absolute oral bioavailability of 0.52 in healthy subjects, supporting high oral bioavailability for this opioid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Morphine, the closest morphinan analogue, had oral bioavailability of 30–40% in healthy volunteers, above the 20% threshold, supporting high F despite first-pass conjugation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pentazocine, a related benzomorphan opioid, had mean oral bioavailability of 18% in healthy subjects, below threshold; however, its phenolic OH and different scaffold make this less transferable to the 3-methoxy-6-keto morphinan query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 3-methoxy-6-keto morphinan (hydrocodone-like). High-transfer experimental evidence from opioid/morphinan analogues—samidorphan 69%, pethidine 52%, and morphine 30–40%—supports oral bioavailability above 20%. The only sub-20% values come from phenolic opioids with extensive first-pass conjugation, a liability absent in the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule; extrapolation relies on close analogues.",
    "Metabolic stability and CYP-mediated clearance of the 6-keto morphinan are not directly measured.",
    "Formulation effects on oral absorption are not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

